\label{thm:principal}
Suppose $\ell\neq p$. Let \(\chi\) be a character of \(E^\times\).\label{mainthm1.1}
\begin{enumerate}
\item If \(\ell \neq 2\) and \(q_E \not\equiv -1 \pmod{\ell}\), then the twisted Steinberg representation \(\mathrm{St}_\chi\) is \(D^\times\)-distinguished if and only if \(\chi|_{F^\times} = \omega_{E/F}\).

\item If \(\ell \neq 2\) and \(q_E \equiv -1 \pmod{\ell}\), then the special representation \(\mathrm{Sp}_\chi\) is \(D^\times\)-distinguished if and only if one of the following conditions holds:
    \begin{enumerate}
        \item $\chi|_{F^\times}=\omega_{E/F}$ and $E/F$ is ramified;
        \item $\chi|_{F^\times}$ is a nontrivial quadratic unramified character and $E/F$ is ramified.
    \end{enumerate}

\item If \(\ell = 2\), then $\mathrm{Sp}_\chi$ is distinguished by $D^\times$ if and only if $\chi|_{F^\times}=\boldsymbol{1}$, $E/F$ is ramified and $q\equiv 3\pmod 4$.
\end{enumerate}

Moreover, in all positive cases, the dimension of the corresponding \(\mathrm{Hom}\) space is one.

This theorem exhibits two phenomena specific to the modular setting.
\begin{itemize}
\item Theorem \ref{thm:principal} (2) condition (b) implies that an irreducible subquotient $\mathrm{Sp}_\chi$ of a principal series representation can be \(D^\times\)-distinguished even when the principal series itself is not. 
Thus distinction of the special representation cannot be detected only from invariant linear forms on the principal series. In our proof, this additional invariant linear form is accounted for by a nonzero extension group;
\item Theorem \ref{thm:principal} (3) shows that when \(\ell=2\), the distinction criterion detects the residue cardinality modulo \(4\). This dependence arises from the extension structure of a finite permutation representation of the dihedral group \(D_{2(q+1)}\).
\end{itemize}

Assume $\ell\neq2$.
Let \( \pi \) be a \( \sigma \)-selfdual supercuspidal \( \overline{\boldsymbol{F}_\ell} \)-representation of \( \mathrm{GL}_2(E) \). Then the following are equivalent:
\begin{enumerate}
\item \( \pi \) is \( \mathrm{GL}_2(F) \)-distinguished;
\item \( \pi \) is not \( (\mathrm{GL}_2(F), \omega_{E/F}) \)-distinguished;
\item the Langlands parameter \( \phi_\pi \) is conjugate-orthogonal.
\end{enumerate}
In particular, a \( \sigma \)-selfdual supercuspidal representation is either \( \mathrm{GL}_2(F) \)-distinguished or \( (\mathrm{GL}_2(F), \omega_{E/F}) \)-distinguished, but not both.

Let $\pi$ be a $\sigma$-selfdual supercuspidal representation of $\mathrm{GL}_2(E)$,
with relative degree $m \in \{1,2\}$ and distinction character $\delta_0$.
\begin{enumerate}
\item If $\ell = 2$, then $\pi$ is always $D^\times$-distinguished.
\item If $\ell \neq 2$ and $p$ is odd, then $\pi$ is $D^\times$-distinguished if and only if 
\begin{align*}
    \begin{cases}
    \delta_0\ \mathrm{is\ the\ trivial\ character},&\mbox{when}\ m=1;\\\
    \delta_0=\omega_{\mathcal{D}/\mathcal{D}_0},&\mbox{when}\ m=2.
\end{cases}
\end{align*}
\end{enumerate}

\label{thm:GL2}
Assume \( \ell = 2 \).
\begin{enumerate}
\item A principal series representation \( \pi(\chi_1, \chi_2) \) of \( \mathrm{GL}_2(E) \) is \( \mathrm{GL}_2(F) \)-distinguished if and only if  
\(
\chi_1 \chi_2^\sigma = \boldsymbol{1}
\)
or  
\(
\chi_1 |_{F^\times} = \chi_2 |_{F^\times} = \boldsymbol{1} \ \text{with} \ \chi_1 \neq \chi_2.
\)
\item The special representation \( \mathrm{Sp}_\chi \) is \( \mathrm{GL}_2(F) \)-distinguished if and only if \( \chi|_{F^\times} = \boldsymbol{1} \).
\end{enumerate}

By the well-known K$\ddot{\mathrm{u}}$nneth formula, we obtain that
    \begin{align*}
        \mathrm{Ext}^1_{F^\times\times F^\times}(\boldsymbol{1},\chi_1\boxtimes\chi_2)=\mathrm{H}^1(F^\times\times F^\times,\chi_1\boxtimes\chi_2)\cong(\mathrm{H}^1(F^\times,\chi_1)\otimes \mathrm{H}^0(F^\times,\chi_2))\oplus(\mathrm{H}^1(F^\times,\chi_2)\otimes \mathrm{H}^0(F^\times,\chi_1))
    \end{align*}
where $\mathrm{H}^0(F^\times,\chi):=\{v|\chi(a)v=v,\forall a\in F^\times\}$. Therefore, $\mathrm{dim\ H}^0(F^\times,\chi)=\begin{cases}
    1,\ \chi|_{F^\times}=\boldsymbol{1};
    \\0,\ \chi|_{F^\times}\neq\boldsymbol{1}.\end{cases}$

If $\chi|_{F^\times}=\boldsymbol{1}, \mathrm{H}^1(F^\times,\chi)=\mathrm{Hom}(F^\times,\overline{\boldsymbol{F}_\ell})$. By the same argument in Proposition \ref{coE},
\begin{align*}
    \dim\ \mathrm{Hom}(F^\times,\overline{\boldsymbol{F}_\ell})=\begin{cases}
        1,\ \ell\nmid q-1;\\
        2,\ \ell\ |\ q-1.
    \end{cases}
\end{align*}
If $\chi|_{F^\times}\neq\boldsymbol{1}$, for any cocycle $f\in\mathrm{H}^1(F^\times,\chi)$, taking $a\in F^\times$ such that $\chi(a)\neq 1$, we have $\forall b\in F^\times$,
\begin{align*}
    f(b)=\dfrac{\chi(b)-1}{\chi(a)-1}f(a)
\end{align*}
since $f(ab)=f(ba)$. Therefore $f$ is a coboundry i.e. $\mathrm{H}^1(F^\times,\chi)=0$.

In summary, $\mathrm{Ext}^1_{F^\times\times F^\times}(\boldsymbol{1},\chi_1\boxtimes\chi_2)\neq0$ if and only if $\chi_1|_{F^\times}=\chi_2|_{F^\times}=\boldsymbol{1}$. Moreover, in this case,
\begin{align*}
    \mathrm{dim}\ \mathrm{Ext}^1_{F^\times\times F^\times}(\boldsymbol{1},\chi_1\boxtimes\chi_2)=\begin{cases}
    2,\ \ell\nmid q-1;\\
        4,\ \ell\ |\ q-1.\\
    \end{cases}
\end{align*}
This finishes the proof.

Followed by \cite[Corollary 1.31]{milneCFT}, if $|G|=p^n$, we have $p^n\mathrm{H}^r(G,A)=0$ for $r\geq1$. 

    We claim that $\mathrm{H}^r(G,A)$ is an $\ell$-torsion, i.e., annihilated by $\ell$. Consider an arbitrary function $\varphi:G^r\longrightarrow A\in \mathrm{H}^r(G,A)$. Since $G$ is finite, $\varphi(G)$ is finite. Denote $\varphi(G)=\{a_1,...,a_k\}$. Since $A$ is an $\ell$-torsion, $\ell\varphi(G)=0$ i.e. $\ell\varphi=0$.

    Since $\ell$ and $p^n$ are coprime, there exists integers $u,v$ such that $u\ell+vp^n=1$. For any $\varphi\in\mathrm{H^r(G,A)},$\begin{align*}
        \varphi=(u\ell+vp^n)\varphi=u\ell\varphi+vp^n\varphi=0
    \end{align*}
    This finishes the proof.

\label{extfix}
    Let $G$ be a profinite group and $U$ be the normal pro-$p$ subgroup of $G$. Assume $\ell\neq p$. Suppose $V$ is a smooth $\overline{\boldsymbol{F}_\ell}$-representation of $G$ and $\boldsymbol{1}$ is the trivial representation of $G$. Taking $U$-invariant induces an isomorphism
    \begin{align*}
        \mathrm{Ext}_G^1(V,\boldsymbol{1})\cong\mathrm{Ext}_{G/U}^1(V^U,\boldsymbol{1})
    \end{align*}
    where $\mathrm{Ext}$ groups are computed in the respective categories of smooth representations.

Let $M$ be an extension of $V$ by the trivial character $\boldsymbol{1}$ in the categories of smooth representations of $G$. There exists an exact sequence:
    \begin{align*}
        0\longrightarrow\boldsymbol{1}\longrightarrow M \stackrel{f}{\longrightarrow} V\longrightarrow0
    \end{align*}
    where $f:M\rightarrow V$ is the quotient map. 
    Since $\ell\neq p$ and $U$ is a pro-$p$ group, the $U$-invariant functor $(-)^U$ is exact due to Corollary \ref{copro-p}. Then we have the following exact sequence
    \begin{align*}
        0\longrightarrow\boldsymbol{1}\longrightarrow M^U \longrightarrow V^U\longrightarrow0.
    \end{align*}
    Then we define a map
    \begin{align*}
\Phi:\mathrm{Ext}_G^1(V,\boldsymbol{1})&\longrightarrow\mathrm{Ext}_{G/U}^1(V^U,\boldsymbol{1})\\
M&\longmapsto M^U.
    \end{align*}

    Conversely, if $M'$ is an extension of $V^U$ by the trivial character $\boldsymbol{1}$ in the categories of smooth representations of $G/U$, then
    \begin{align*}
        0\longrightarrow\boldsymbol{1}\longrightarrow M' \stackrel{f'}{\longrightarrow} V^U\longrightarrow0
    \end{align*}
    is exact.
    Followed by \cite[Section 12.6:Extensions]{stacks-project}, denote $e_U:V\longrightarrow V^U$ the averaging projection. Then $M'$ has a pullback $\overline{M'}=M'\times_{V^U}V$, which is defined as:
    \begin{align*}
        \overline{M'}:=\{(x,v)|x\in M',v\in V\ \mathrm{satisfying}\ f'(x)=e_U(v)\}.
    \end{align*}
    Then we define another map
    \begin{align*}
        \Psi:\mathrm{Ext}_{G/U}^1(V^U,\boldsymbol{1})&\longrightarrow\mathrm{Ext}_G^1(V,\boldsymbol{1})\\
        M'&\longmapsto\overline{M'}
    \end{align*}

    Next we need to prove that $\Psi,\Phi$ are mutually inverse. Consider $\Psi\circ\Phi$, $\forall x\in M, \Psi\circ\Phi(x)=(e_U(x),f(x))$. Then $\Psi\circ\Phi$ induces isomophisms $\boldsymbol{1}\cong\boldsymbol{1}$ and $V\cong\Psi\circ\Phi(V)$ in the category of smooth representaions of $G$. By the snake Lemma, $M\cong\Psi\circ\Phi(M)$.

    For $\Phi\circ\Psi$, $\forall x'\in M'$,
    \begin{align*}
        \Phi\circ\Psi(x)=\{(x,v)|x\in M',v\in V^U\ \mathrm{satisfying}\ f'(x)=v\}.
    \end{align*}
    Thus we have an isomorphism $M'\cong\Phi\circ\Psi(M')$. This finishes the proof.

\label{exth1}
    With the same notations as in Proposition \ref{extfix}, suppose $\ell\neq p$ and $G/U$ is a finite group. Then there exists an isomorphism
    \begin{align*}
        \mathrm{Ext}_G^1(V,\boldsymbol{1})\cong \mathrm{H}^1(G/U,(V^U)^\vee)
    \end{align*}
    where $(V^U)^\vee$ is the dual space of $V^U$.

Followed by Proposition \ref{extfix} and \cite[Theorem 3.2.1]{Jenda00},
    \begin{align*}
    \mathrm{Ext}^1_G(V,\boldsymbol{1})\cong\mathrm{Ext}_{G/U}^1(V^U,\boldsymbol{1})\cong\mathrm{Ext}^1_{G/U}(\boldsymbol{1},(V^U)^\vee)
    \end{align*} 
    then $\mathrm{Ext}^1_{G/U}(\boldsymbol{1},(V^U)^\vee)\cong\mathrm{H}^1(G/U,(V^U)^\vee)$.

There exists a short sequence:
    \begin{align*}
        1\longrightarrow\mathrm{SL}_2(F)\longrightarrow\mathrm{GL}_2(F)\stackrel{\det}{\longrightarrow}F^\times\longrightarrow1
    \end{align*}
    By the Hochschild-Serre spectral sequence, we have 
    \begin{align*}
        0\longrightarrow\mathrm{H}^1(F^\times,\boldsymbol{1})\longrightarrow\mathrm{H}^1(\mathrm{GL}_2(F),\boldsymbol{1})\longrightarrow\mathrm{H}^1(\mathrm{SL}_2(F),\boldsymbol{1})^{F^\times}.
    \end{align*}
    For $\mathrm{H}^1(\mathrm{SL}_2(F),\boldsymbol{1})$, it equals $\mathrm{Hom}(\mathrm{SL}_2(F),\overline{\boldsymbol{F}_2})$. Since $\overline{\boldsymbol{F}_2}$ is Abelian, we consider $\mathrm{SL}_2(F)^{ab}$, the Abelianization of $\mathrm{SL}_2(F)$ which is the identity element since $\mathrm{SL}_2(F)$ is perfect. Then, $\mathrm{H}^1(\mathrm{SL}_2(F),\boldsymbol{1})=0$.

    Followed by the spectral sequence above and the same argument in Proposition \ref{coE}:
    \begin{align*}
        \mathrm{Ext}^1_{\mathrm{GL}_2(F)}(\boldsymbol{1},\boldsymbol{1})=\mathrm{H}^1(\mathrm{GL}_2(F),\boldsymbol{1})=\mathrm{H}^1(F^\times,\boldsymbol{1})=\mathrm{Hom}(F^\times,\overline{\boldsymbol{F}_2})
    \end{align*}
    and its dimension is 2 since $\ell\ |\ (q-1)$.

\label{3.3}
         Assume $\ell\neq2$ and $p\neq2$. Let $\chi$ be a character of $F^\times$ and denote $\chi\circ\det$ the character of $D^\times
         $. Let $Z=F^\times$ be the center of $D^\times$.
         \begin{enumerate}
             \item If $\chi^2\neq\boldsymbol{1}$, then $\mathrm{dim}$\ $\mathrm{Ext}_{D^\times}^1(\boldsymbol{1},\chi\circ\det)=0$.
             \item If $\chi^2=\boldsymbol{1}$ and $\chi\neq\boldsymbol{1}$, then
             \begin{align*}
                 \mathrm{dim}\ \mathrm{Ext}_{D^\times}^1(\boldsymbol{1},\chi\circ\det)=\begin{cases}
            1,\ \mathrm{if}\ \chi\circ\det|_{C_{q+1}}=\boldsymbol{1}\ \mathrm{and}\ \ell|q+1;\\
            0,\ \mathrm{others,}
        \end{cases}
             \end{align*}
             where $C_{q+1}=\boldsymbol{k}_D^\times/\boldsymbol{k}_F^\times.$
             Moreover, $\mathrm{dim}\ \mathrm{Ext}_{D^\times}^1(\boldsymbol{1},\chi\circ\det)=\mathrm{dim}\ \mathrm{Ext}_{PD^\times}^1(\boldsymbol{1},\chi\circ\det)$.
             \item If $\chi=\boldsymbol{1}$, $\mathrm{dim}$\  $\mathrm{Ext}_{PD^\times}^1(\boldsymbol{1},\boldsymbol{1})=0$.
         \end{enumerate}
         Here $\mathrm{Ext}_{D^\times}^1$(resp. $\mathrm{Ext}_{PD^\times}^1$) is the $\mathrm{Ext}$ functor in the category of the smooth representation of $D^\times$(resp. $PD^\times$).

We have $\mathrm{GL}_2(E)/B_2(E)\simeq\mathbb{P}^1(E)$, so we only need to consider the number of orbits of the action of $D^\times$ on $\mathbb{P}^1(E)$.The action of $D^\times$ on $\mathbb{P}^1(E)$ is defined as
        \begin{align*}
            \begin{pmatrix}
                \alpha&b\beta\\
            \sigma(\beta)&\sigma(\alpha)
            \end{pmatrix}\cdot x:=\dfrac{\alpha x+b\beta}{\sigma(\beta)x+\sigma(\alpha)}
        \end{align*}
     We claim that the action is transitive, that is, $\forall x\in\mathbb{P}^1(E)$,there exists $d\in D^\times$ such that $d\cdot0=x$.

     If $x=\infty$,let $d=\begin{pmatrix}
         0&b\\
         1&0
     \end{pmatrix}\in D^\times$,then $d\cdot0=\dfrac{b}{0}=\infty$.

     If $x=t\in E$,let $d=\begin{pmatrix}
         1&t\\
         b^{-1}\sigma(t)&1
     \end{pmatrix}\in D^\times$, then $d\cdot0=\dfrac{d}{1}=t$.

\label{3.2}
         Let $\pi=\pi(\chi_1,\chi_2)$ be a principal series representation of $\mathrm{GL}_2(E)$. Then $\pi$ is distinguished by $D^\times$ if and only if $\chi_1\chi_2^\sigma=\boldsymbol{1}$.
         Moreover,we have
         \begin{align*}
            \mathrm{dim}\ \mathrm{Hom}_{D^\times}(\pi,\boldsymbol{1})=\begin{cases}
                 1,\  if\ \chi_1\chi_2^\sigma=\boldsymbol{1},\\
                 0,\  otherwise.
             \end{cases}
         \end{align*}

By Lemma \ref{3.1} and Mackey Theory, we have $\mathrm{Res}_{D^\times}^G\mathrm{Ind}_{B_2(E)}^G(\chi_1\boxtimes\chi_2)=\mathrm{Ind}_{D^\times\cap B_2(E)}^{D^\times}\chi_1\boxtimes \chi_2$. Then
         \begin{align*}
             \mathrm{Hom}_{D^\times}(\pi,\boldsymbol{1})=\mathrm{Hom}_{D^\times}(\mathrm{Ind}_{D^\times\cap B_2(E)}^{D^\times}\chi_1\boxtimes\chi_2,\boldsymbol{1})=\mathrm{Hom}_{D^\times\cap B_2(E)}(\chi_1\boxtimes\chi_2,\boldsymbol{1}).
         \end{align*}
         Because $B_2(E)\cap D^\times=\left\{\begin{pmatrix}
             \alpha&\\
             &\sigma(\alpha)
         \end{pmatrix}|\alpha\in E,\mathrm{Nm}_{E/F}(\alpha)\neq 0\right\}\simeq E^\times$, one has $$\mathrm{dim}\ \mathrm{Hom}_{D^\times}(\pi,\boldsymbol{1})=\begin{cases}
                 1,\  if\ \chi_1\chi_2^\sigma=\boldsymbol{1},\\
                 0,\  otherwise.
             \end{cases}$$
             This finishes the proof.

\label{l4.2}
    Suppose $\ell\neq p$, $\pi=\pi(\chi\nu^{1/2},\chi\nu^{-1/2})$, $\chi$ is a character of $E^\times$ and $\chi^2|_{F^\times}=\boldsymbol{1}$. Then
    $\pi(\chi\nu^{1/2},\chi\nu^{-1/2})|_{D^\times}$ can be seen as a representation of $PD^\times$ and
    \begin{align*}
       \dim\ \mathrm{Ext}_{PD^\times}^1(\pi,\boldsymbol{1})=\begin{cases}
        1,& \mathrm{if\ }E/F\ \mathrm{is\ unramified}, \chi\chi^\sigma=\boldsymbol{1}\ \mathrm{and}\  \ell|q+1;\\
        1,& \mathrm{if\ }E/F\ \mathrm{is\ ramified\ and}\ \ell=2;\\
        0,& \mathrm{otherwise}.
    \end{cases}
    \end{align*}
    In particular, the lemma also holds when $p=2$.

Followed by Corollary \ref{exth1}, since $PD^\times/U_1\simeq D_{2(q+1)}$ is a finite group, we have
    \begin{align*}
        \mathrm{Ext}_{PD^\times}^1(\pi,\boldsymbol{1})\cong \mathrm{H}^1(D_{2(q+1)},(\pi^{U_1})^\vee).
    \end{align*}
    where $(\pi^{U_1})^\vee$ denotes the linear dual space of $\pi^{U_1}$.
    Then we will first determine $\pi^{U_1}$. According to the proof of Lemma \ref{3.2} and $\chi^2|_{F^\times}=\boldsymbol{1}$, $\mathrm{Res}_{D^\times}^G\pi=\mathrm{Ind}_{E^\times}^{D^\times}\chi\chi^\sigma=\mathrm{Ind}_{E^\times/F^\times}^{PD^\times}\chi\chi^\sigma$. Therefore, $\pi^{U_1}=(\mathrm{Res}_{D^\times}^G\pi)^{U_1}=(\mathrm{Ind}_{E^\times/F^\times}^{PD^\times}\chi\chi^\sigma)^{U_1}$. If $\pi^{U_1}=0$, $\mathrm{Ext}_{PD^\times}^1(\pi,\boldsymbol{1})=0$. Now we suppose $\pi^{U_1}\neq0$. The elements in $\pi^{U_1}$ are of the form:
    \begin{align*}
        \{f:PD^\times\rightarrow\overline{\boldsymbol{F}_\ell}|f(tg)=\chi\chi^\sigma(t) f(g),f(gu)=f(g),\forall t\in E^\times/F^\times,u\in U_1,g\in PD^\times\}.
    \end{align*}
    Choosing $g_0\in PD^\times$ such that $f(g_0)\neq0$, $\forall t\in(E^\times/F^\times)\cap U_1$, consider $f(tg_0)$:
    \begin{align*}
        f(tg_0)&=\chi\chi^\sigma(t)f(g_0)\\
        f(tg_0)&=f(g_0(g_0^{-1}tg_0))=f(g_0).
    \end{align*}
    The second equality holds since $U_1\lhd PD^\times$ is a normal subgroup. Then $\chi\chi^\sigma$ is trivial on $(E^\times/F^\times)\cap U_1$ which implies $\chi\chi^\sigma$ can be seen as a character of $(E^\times/F^\times)/({E^\times/F^\times\cap U_1})\simeq(E^\times/F^\times)U_1/U_1$. Therefore 
\begin{align*}
    \pi^{U_1}&=(\mathrm{Ind}_{E^\times/F^\times}^{PD^\times}\chi\chi^\sigma)^{U_1}\\
&=\mathrm{Ind}_{(E^\times/F^\times)U_1/U_1}^{PD^\times/U_1}\chi\chi^\sigma\\
&=\begin{cases}
        \mathrm{Ind}_{C_{q+1}}^{D_{2(q+1)}}\chi\chi^\sigma,\   \mathrm{if}\ E/F\ \mathrm{is\ unramified};\\
        \mathrm{Ind}_{C_2}^{D_{2(q+1)}}\chi\chi^\sigma,\   \mathrm{if}\ E/F\ \mathrm{is\ ramified}.
    \end{cases}
\end{align*}
By the Shapiro Lemma,
   \begin{align*}
   \mathrm{H}^1(D_{2(q+1)},(\pi^{U_1})^\vee)=\begin{cases}
           \mathrm{H}^1(D_{2(q+1)},\mathrm{Ind}_{C_{q+1}}^{D_{2(q+1)}}(\chi\chi^\sigma)^{-1})\cong\mathrm{H}^1(C_{q+1},(\chi\chi^\sigma)^{-1}),&   \mathrm{if}\ E/F\ \mathrm{is\ unramified};\\
           \mathrm{H}^1(D_{2(q+1)},\mathrm{Ind}_{C_{2}}^{D_{2(q+1)}}(\chi\chi^\sigma)^{-1})\cong\mathrm{H}^1(C_{2},(\chi\chi^\sigma)^{-1}),&   \mathrm{if}\ E/F\ \mathrm{is\ ramified}.
       \end{cases}
   \end{align*}
    \cite[Chapter VIII, Section 4]{serre1979local} shows that for $\mathrm{H}^1(G,A)$ with a cyclic group $G$ and a nontrivial one-dimensional module $A$, $\mathrm{H}^1(G,A)=0$. 

   Therefore, when $E/F$ is unramified, assuming $\chi\chi^\sigma=\boldsymbol{1}$, we have $\mathrm{H}^1(C_{q+1},(\chi\chi^\sigma)^{-1})\cong \mathrm{Hom}(C_{q+1},\overline{\boldsymbol{F}_\ell})$ and its dimension is one if and only if $\ell|q+1$. 

   If $E/F$ is ramified, suppose $\chi\chi^\sigma=\boldsymbol{1}$. We have $\mathrm{H}^1(C_{2},(\chi\chi^\sigma)^{-1})\cong \mathrm{Hom}(C_{2},\overline{\boldsymbol{F}_\ell})$ and its dimension is one if and only if $\ell=2$. Moreover, in this case, since $\chi^2|_{F^\times}=\boldsymbol{1}$, $\chi|_{F^\times}=\boldsymbol{1}$ and then $\chi\chi^\sigma=\boldsymbol{1}$ is automatically satisfied.

This proves the lemma.

\label{thm1}
        Let $\chi$ be a character of $E^\times$ and $p$ be an odd prime.
        \begin{enumerate}
            \item If $q_E^2\not\equiv1(\mathrm{mod}\ \ell)$, then $\mathrm{St}_\chi$ is distinguished if and only if $\chi|_{F^\times}=\omega_{E/F}$.
            \item If $q_E\equiv1(\mathrm{mod}\ \ell)$, then $\mathrm{St}_\chi$ is distinguished if and only if $\chi|_{F^\times}=\omega_{E/F}$.
            \item If $q_E\equiv-1(\mathrm{mod}\ \ell)$, then $\mathrm{Sp}_\chi$ is distinguished if and only if one of the following conditions holds:
            \begin{enumerate}
                \item $\chi|_{F^\times}=\omega_{E/F}\ \mathrm{and}\ E/F\ \mathrm{is\ ramified}$.
                \item $\chi|_{F^\times}\ \mathrm{is\ a\ nontrivial\  quadratic\ unramified\ character\ and}\ E/F\ \mathrm{is\ ramified}$.
            \end{enumerate}
        \end{enumerate}
        Moreover, if $\mathrm{St}_\chi$ or $\mathrm{Sp}_\chi$ is distinguished, the dimension of $\mathrm{Hom}_{D^\times}(\mathrm{St}_\chi,\boldsymbol{1})$ or $\mathrm{Hom}_{D^\times}(\mathrm{Sp}_\chi,\boldsymbol{1})$ is one.

\label{p2quadratic}
    In the case $p=2$, when $\chi^2|_{F^\times}=\boldsymbol{1}$ but $\chi|_{F^\times}\neq\boldsymbol{1}$, we have $$\mathrm{dim}\ \mathrm{Ext}_{D^\times}(\boldsymbol{1},\chi\circ\det)=\begin{cases}
        1,\ \mathrm{if}\ \chi|_{F^\times}\ \mathrm{is\ unramified\ and}\  \ell|q+1;\\
        0,\ \mathrm{otherwise}.
    \end{cases}$$

Thanks to the exact sequence \eqref{f1} and $\mathrm{H}^1(F^\times,(\chi\circ\det))^{PD^\times}=0$ in Lemma \ref{3.3}, we have $\mathrm{H}^1(D^\times,\chi\circ\det)=\mathrm{H}^1(PD^\times,\chi\circ \det)$. Consider the exact sequence \eqref{f2}:
    \begin{align*}
            0\longrightarrow \mathrm{H}^1(D_{2(q+1)},(\chi\circ\det)^{U_1})\longrightarrow\mathrm{H}^1(PD^\times,\chi\circ\det)\longrightarrow \mathrm{H}^1(U_1,\chi\circ\det)^{D_{2(q+1)}}.
        \end{align*}
    where $U_1=(1+\mathfrak{p}_D)F^\times/F^\times$.

    When $\chi|_{F^\times}$ is ramified, since $\chi|_{F^\times}$ is quadratic and $p=2$, $\chi|_{F^\times}$ is trivial on $\mathcal{O}_F^\times/(1+\mathfrak{p}_F)\cong C_{q-1}$. Then $\chi|_{F^\times}$ is not trivial on $1+\mathfrak{p}_F$; otherwise $\chi|_{F^\times}$ is trivial on $\mathcal{O}_F^\times$ contradicting the fact that $\chi$ is ramified. The map $\det|_{1+\mathfrak{p}_D}:1+\mathfrak{p}_D\longrightarrow1+\mathfrak{p}_F$ is surjective and so $\chi\circ\det$ is not trivial on $U_1$. Then $(\chi\circ\det)^{U_1}=0$ and $\mathrm{H}^1(D_{2(q+1)},(\chi\circ\det)^{U_1})=0$.

    For $\mathrm{H}^1(U_1,\chi\circ\det)$, $U_1$ is a pro-2 group and $\chi\circ\det$ is a discrete $\ell$-torsion module and $\ell\neq 2$. Followed by Corollary \ref{copro-p}, $\mathrm{H}^1(U_1,\chi\circ\det)=0$. Therefore, when $\chi$ is ramified, we have $$\mathrm{H}^1(D^\times,\chi\circ\det)=\mathrm{H}^1(PD^\times,\chi\circ\det)=0.$$
    When $\chi|_{F^\times}$ is unramified, $\chi|_{\mathcal{O}_F^\times}=\boldsymbol{1}$ and $\chi(\varpi_F)=-1$. Then $\chi\circ\det$ is trivial on $\mathcal{O}_D^\times$ especially on $U_1$. In this case, 
    \begin{align*}
        (\chi\circ\det)^{U_1}=\chi\circ\det, \ \mathrm{H}^1(U_1,\chi\circ\det)=\mathrm{Hom}(U_1,\overline{\boldsymbol{F}_\ell})=0\ \mathrm{since}\ \ell\neq p.
    \end{align*}
     Now, we likewise only need to compute $\mathrm{H}^1(D_{2(q+1)},\chi\circ\det)$. If $p=2$, $q+1$ is odd and so $\chi\circ\det$ must be trivial over $C_{q+1}$. The remaining argument is the same as the case $\chi\circ\det|_{C_{q+1}}=\boldsymbol{1}$ in Lemma \ref{3.3}. Therefore, when $\chi$ is unramified, dim $\mathrm{Ext}_{D^\times}^1(\boldsymbol{1},\chi\circ\det)=\begin{cases}
         1,\ \ell|\ q+1;\\
         0,\ \mathrm{otherwise}.
     \end{cases}$

     In a short summary, $\mathrm{dim}\ \mathrm{Ext}_{D^\times}^1(\boldsymbol{1},\chi\circ\det)=\begin{cases}
        1,& \mathrm{if}\ \chi|_{F^\times}\ \mathrm{is\ unramified\ and}\  \ell|\ q+1;\\
        0,& \mathrm{otherwise}.
    \end{cases}$.

\label{pSp2}
    When $p=2$, $q_E\equiv-1(\mathrm{mod}\ \ell)$, $\mathrm{Sp}_\chi$ is distinguished if and only if one of the following conditions holds:
    \begin{enumerate}
        \item $\chi|_{F^\times}=\omega_{E/F}$ and $E/F$ is ramified;
        \item $\chi|_{F^\times}$ is a nontrivial quadratic unramified character and $E/F$ is ramified.
    \end{enumerate}
    Moreover, if $\mathrm{Sp}_\chi$ is distinguished, the dimension of $\mathrm{Hom}_{D^\times}(\mathrm{Sp}_\chi,\boldsymbol{1})$ is 1.

Suppose $\pi$ is distinguished. Then the central character restricting the center $Z(D^\times)$ is trivial. We can reduce to the case for $PD^\times$. If $\chi|_{F^\times}$ is trivial, then $\mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})=0$ and $\mathrm{Hom}_{PD^\times}(J_\chi,\boldsymbol{1})=0$ implies that $\mathrm{Sp}_\chi$ is not distinguished due to \eqref{f35}. 

If $\chi|_{F^\times}=\omega_{E/F}$, supposing $E/F$ is unramified, then $\ell|\ q^2+1$ shows that $\ell\nmid q+1$. Followed by Lemma \ref{p2quadratic}, $\mathrm{Ext}_{D^\times}(\chi\circ\det,\boldsymbol{1})=0$. Then $$\dim \mathrm{Hom}_{D^\times}(J_\chi,\boldsymbol{1})=\dim \mathrm{Hom}_{D^\times}((\chi\circ\det)\nu_2,\boldsymbol{1})=1.$$ Since $\ell\nmid 2(q+1)$, $\mathrm{Ext}_{PD^\times}^1(\mathrm{Sp}_\chi,\boldsymbol{1})\cong\mathrm{Ext}_{D_{2(q+1)}}^1((\mathrm{Sp}_\chi)^{U_1},\boldsymbol{1})=0$ by Maschke's Theorem. The map $\mathrm{Hom}_{D^\times}(J_\chi,\boldsymbol{1})\longrightarrow\mathrm{Hom}_{D^\times}(\boldsymbol{1},\boldsymbol{1})$ is surjective and so $\mathrm{Sp}_\chi$ is not distinguished.

Now suppose $E/F$ is ramified. Then $\omega_{E/F}$ is ramified. Using Lemma \ref{p2quadratic}, $\mathrm{Ext}_{D^\times}^1(\chi\circ\det,\boldsymbol{1})=0$. Followed by the exact sequences \eqref{f34} and \eqref{f35}, we have the isomorphisms:
\begin{align*}
    \mathrm{Hom}_{D^\times}(\pi,\boldsymbol{1})\cong \mathrm{Hom}_{D^\times}(J_\chi,\boldsymbol{1})\ \mathrm{and}\ \mathrm{Hom}_{D^\times}(\mathrm{Sp}_\chi,\boldsymbol{1})\cong \mathrm{Hom}_{D^\times}(J_\chi,\boldsymbol{1})
\end{align*}
Since $\dim \mathrm{Hom}_{D^\times}(\pi,\boldsymbol{1})= 1$, $\mathrm{Hom}_{D^\times}(\mathrm{Sp}_\chi,\boldsymbol{1})\neq 0$ i.e., $\mathrm{Sp}_\chi$ is distinguished and its dimension is 1.\\

Suppose $\pi$ is not distinguished. We only consider the case $\chi^2|_{F^\times}=\boldsymbol{1}$ with $\chi|_{F^\times}\not\in\{\boldsymbol{1},\omega_{E/F}\}$. If $E/F$ is unramified, then $\ell\nmid q+1$. Lemma \ref{p2quadratic} implies $\mathrm{Ext}_{D^\times}(\chi\circ\det,\boldsymbol{1})=0$. Then $\mathrm{Sp}_\chi$ is not distinguished since $\mathrm{Hom}_{D^\times}(J_\chi,\boldsymbol{1})=0$. If $E/F$ is ramified, Lemma \ref{l4.2} implies $\mathrm{Ext}_{PD^\times}^1(\pi,\boldsymbol{1})=0$ and $\mathrm{Hom}_{PD^\times}((\chi\circ\det)\nu_2,\boldsymbol{1})=\mathrm{Hom}_{D^\times}((\chi\circ\det)\nu_2,\boldsymbol{1})=0$. Thus we have 
\begin{align*}
    \mathrm{Hom}_{D^\times}(\mathrm{Sp}_\chi,\boldsymbol{1})\simeq\mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})
\end{align*}
by the exact sequences \eqref{f34} and \eqref{f35}. Therefore $\mathrm{Sp}_\chi$ is distinguished if and only if $\chi|_{F^\times}$ is unramified, which is followed by Lemma \ref{p2quadratic}. 
This finished the proof.

\label{thm41}
    Assume $\ell=2$.
     The irreducible representation   $\mathrm{Sp}_\chi$ is distinguished by $D^\times$ if and only if $\chi|_{F^\times}=\boldsymbol{1}$, $E/F$ is ramified and $q\equiv 3\pmod 4$.

We have two exact sequences
            \begin{align*}\label{expi}
                0\longrightarrow M\longrightarrow \pi(\chi,\chi)&\longrightarrow\chi\circ\det\longrightarrow0\tag{4-4}
            \end{align*}
            and
            \begin{align*}\label{f41}
                0\longrightarrow\chi\circ\det\longrightarrow &M\longrightarrow\mathrm{Sp}_\chi\longrightarrow0\tag{4-5}
            \end{align*}

        If $\pi(\chi,\chi)$ is not distinguished, we must have $\chi|_{F^\times}\neq\boldsymbol{1}$; otherwise  $\chi\chi^\sigma=\chi|_{F^\times}\circ \mathrm{Nm}_{E/F}$ is trivial, which will imply that $\pi(\chi,\chi)$ is distinguished by $D^\times$. Then $\chi^2|_{F^\times}\neq\boldsymbol{1}$ since $\ell=2$ and so
         $\mathrm{Sp}_\chi$ is not distinguished.

        Suppose that $\pi(\chi,\chi)$ is distinguished, i.e., $\chi\chi^\sigma=\boldsymbol{1}$. Then $\chi^2|_{F^\times}=\boldsymbol{1}$ which means $\chi|_{F^\times}=\boldsymbol{1}$.
        Each element in $\pi(\chi,\chi)$ is of the form 
        \begin{align*}
            \{f:G\rightarrow \overline{\boldsymbol{F}_2}\ |f\  \mathrm{is \ smooth\ and}\ f(bg)=\chi(a)\chi(d)f(g),\forall b=\begin{pmatrix}
                a&x\\
                &d
            \end{pmatrix},g\in G\}
        \end{align*}
        Therefore, $\forall z\in Z(D^\times)=F^\times, z\cdot f(g)=f(g\cdot zI_2)=f(zI_2\cdot g)=\chi^2(z)f(g)=f(g)$. We have that $z$ acts trivially on $\pi(\chi,\chi)$. Then $\pi(\chi,\chi)$ can be viewed as a representation of $PD^\times$ and $\mathrm{Hom}_{D^\times}(\pi(\chi,\chi),\boldsymbol{1})=\mathrm{Hom}_{PD^\times}(\pi(\chi,\chi),\boldsymbol{1})$, so are $M$ and $\chi\circ\det$. Taking the funcor $\mathrm{Hom}_{PD^\times}(-,\boldsymbol{1})$, we get the long exact sequence
        \begin{align*}\label{f42}
            0&\longrightarrow\mathrm{Hom}_{PD^\times}(\chi\circ\det,\boldsymbol{1})\stackrel{f_1}{\longrightarrow}\mathrm{Hom}_{PD^\times}(\pi(\chi,\chi),\boldsymbol{1})\stackrel{f_2}{\longrightarrow}\mathrm{Hom}_{PD^\times}(M,\boldsymbol{1})\\
            &\stackrel{f_3}{\longrightarrow} \mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})\stackrel{f_4}{\longrightarrow}\mathrm{Ext}_{PD^\times}^1(\pi(\chi,\chi),\boldsymbol{1})\tag{4-6}
        \end{align*}
        where $f_i$ denotes the corresponding map.
In this case,  $$\dim\mathrm{Hom}_{PD^\times}(\chi\circ\det,\boldsymbol{1})= \dim \mathrm{Hom}_{PD^\times}(\pi(\chi,\chi),\boldsymbol{1})=1$$ and $f_1$ is injective. Therefore $f_1$ is an isomorphism. By the exactness of \eqref{f42}, $f_2$ is a zero map and $f_3$ is injective. According to the dimension formula of the exact sequence,
\begin{align*} \label{f43}
    \mathrm{dim}\ \mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})=\mathrm{dim\ Ker}f_4+\mathrm{dim\ Im}f_4=\mathrm{dim}\ \mathrm{Hom}_{PD^\times}(M,\boldsymbol{1})+ \mathrm{dim\ Im}f_4\tag{4-7}
\end{align*}
For the dimension of $\mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})$, by the exact sequence \eqref{f2} , \begin{align*}
