\end{align*}
 since $\ell\neq p$ and $\chi|_{F^\times}=\boldsymbol{1}$. Then the dimension is 2. For $\mathrm{Ext}^1_{PD^\times}(\pi(\chi,\chi),\boldsymbol{1})$, Lemma \ref{l4.2} shows that $\dim\ \mathrm{Ext}^1_{PD^\times}(\pi(\chi,\chi),\boldsymbol{1})=1$ since $\ell=2$ and $\ell|\ (q+1)$.

Therefore, we just need to determine the dimension of $\mathrm{Im}$ $f_4$.

\begin{lem}\label{l4.3}
Let $\pi=\pi(\chi,\chi)$.
   The map $f_4:\mathrm{Ext}^1_{PD^\times}(\chi\circ\det,\boldsymbol{1})\rightarrow \mathrm{Ext}_{PD^\times}^1(\pi,\boldsymbol{1})$ is surjective. In other words, $\mathrm{dim\ Im}\ f_4=1$.
\end{lem}
\begin{proof}
Recall that $U_1$ is the pro-$p$ subgroup of $PD^\times$ such that $PD^\times/U_1\cong D_{2(q+1)}$.
Note that $$\mathrm{H}^1(D_{2(q+1)},(\pi^{U_1})^\vee)\cong\begin{cases}
        \mathrm{H}^1(C_{q+1},\boldsymbol{1}),&   \mathrm{if}\ E/F\ \mathrm{is\ unramified};\\
        \mathrm{H}^1(C_2,\boldsymbol{1}),&   \mathrm{if}\ E/F\ \mathrm{is\ ramified}.\\
    \end{cases}$$
We have $\mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})\cong\mathrm{H}^1(D_{2(q+1)},\boldsymbol{1})$ and $\mathrm{Ext}_{PD^\times}^1(\pi,\boldsymbol{1})\cong \mathrm{H}^1(D_{2(q+1)},(\pi^{U_1})^\vee)$. Then  
\begin{align*}
    f_4: \mathrm{H}^1(D_{2(q+1)},\boldsymbol{1})\longrightarrow\mathrm{H}^1(D_{2(q+1)},(\pi^{U_1})^\vee)
\end{align*}
is the restriction map by \cite[Example 1.27(b)]{milneCFT}.

    If $E/F$ is unramified, taking $\psi\in\mathrm{Hom}(C_{q+1},\overline{\boldsymbol{F}_2})=\mathrm{H}^1(C_{q+1},\boldsymbol{1})$, we can define $\varphi\in\mathrm{Hom}(D_{2(q+1)},\overline{\boldsymbol{F}_2})=\mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})$ as follows:
    \begin{align*}
        \varphi:D_{2(q+1)}\longrightarrow\overline{\boldsymbol{F}_2},\quad \varphi(r)=\psi(r)\ \mathrm{and}\ \varphi(s)=0
    \end{align*}
    where $r$ and $s$ are generators of the dihedral group $D_{2(q+1)}$ satisfying $r^{q+1}=1$ and $s^2=1$.

    If $E/F$ is ramified, taking $\psi\in\mathrm{Hom}(C_{2},\overline{\boldsymbol{F}_2})=\mathrm{H}^1(C_2,\boldsymbol{1})$, we can define $\varphi\in\mathrm{Hom}(C_2\times C_2,\overline{\boldsymbol{F}_2})=\mathrm{Ext}_{PD^\times}^1(\chi\circ\det,\boldsymbol{1})$ as follows:
    \begin{align*}
        \varphi:C_2\times C_2\longrightarrow\overline{\boldsymbol{F}_2},\quad \varphi(a,b)=\psi(a),\forall a,b\in C_2.
    \end{align*}
    Therefore $f_4$ is a surjective map and $\dim \mathrm{Im} f_4=1$.
\end{proof}
Let us back to the proof of Theorem \ref{thm41}.
Followed by the equality \eqref{f43} and Lemma \ref{l4.3},  $\dim\mathrm{Hom}_{PD^\times}(M,1)$=1. Taking the functor $\mathrm{Hom}_{PD^\times}(-,\boldsymbol{1})$ on the exact sequence \eqref{f41}:
\begin{align*}\label{Mhom}
    0\longrightarrow \mathrm{Hom}_{PD^\times}(\mathrm{Sp}_\chi,\boldsymbol{1})\longrightarrow \mathrm{Hom}_{PD^\times}(M,\boldsymbol{1})\stackrel{f_5}{
    \longrightarrow
    }\mathrm{Hom}_{PD^\times}(\chi\circ\det,\boldsymbol{1})\tag{4-8}
\end{align*}
Since $\dim \mathrm{Hom}_{PD^\times}(M, \mathbf{1}) = \dim \mathrm{Hom}_{PD^\times}(\chi \circ \det, \mathbf{1}) = 1$, we only need to figure out whether $f_5$ is a zero map or an isomorphism.

\begin{lem}\label{f5zero}
The map $f_5$ is a zero map if and only if $E/F$ is ramified and $q\equiv3\pmod4$.
\end{lem}
\begin{proof}
    Since $U_1=(1+\mathfrak{p}_D)F^\times/F^\times$ is a normal open subgroup of $PD^\times$, for any smooth representation $V$, there exists an isomorphism 
    \begin{align*}
        \mathrm{Hom}_{PD^\times}(V,\boldsymbol{1})\simeq\mathrm{Hom}_{PD^\times/U_1}(V^{U_1},\boldsymbol{1})
    \end{align*}
    where $PD^\times/U_1\simeq D_{2(q+1)}$. Then we can rewrite the exact sequence \eqref{Mhom}:
    \begin{align*}
    0\longrightarrow \mathrm{Hom}_{D_{2(q+1)}}(\mathrm{Sp}_\chi^{U_1},\boldsymbol{1})\longrightarrow \mathrm{Hom}_{D_{2(q+1)}}(M^{U_1},\boldsymbol{1})\stackrel{f_5}{
    \longrightarrow
    }\mathrm{Hom}_{D_{2(q+1)}}(\boldsymbol{1},\boldsymbol{1})\simeq\overline{\boldsymbol{F}_2}.
\end{align*}

To determine $M^{U_1}$, taking the $U_1-$fixed functor on the exact sequence \eqref{expi}, we have
\begin{align*}
    0\longrightarrow M^{U_1}\longrightarrow \pi^{U_1}\stackrel{\varepsilon}\longrightarrow\overline{\boldsymbol{F}_2}\longrightarrow0
\end{align*}
since  $\chi|_{F^\times}=\boldsymbol{1}$. Here $\varepsilon$ is the quotient map which will be defined explicitly later. 

Followed by the structure of $\pi^{U_1}$ in Lemma \ref{l4.2}, since $\chi\chi^\sigma=\boldsymbol{1}$, $\pi^{U_1}=(\mathrm{Ind}_{E^\times/F^\times}^{PD^\times}\boldsymbol{1})^{U_1}$. We just need to consider the \((E^\times/F^\times, U_1)\)-double cosets of \(PD^\times\). Denote $$ PD^\times/U_1 \simeq D_{2(q+1)} = \langle r, s \mid r^{q+1} = s^2 = 1, srs = r^{-1} \rangle.$$ When \(E/F\) is unramified, there are 2 representatives \(\{1, s\}\) in the double cosets and \(f \in \pi^{U_1}\) is uniquely determined by \(f(1), f(s)\); when \(E/F\) is ramified, there are \(q+1\) representatives \(\{1, r, \cdots, r^q\}\) and \(f \in \pi^{U_1}\) is uniquely determined by \(f(1), f(r), \cdots, f(r^q)\). 
In a short summary, $$\pi^{U_1}\simeq \begin{cases}
\overline{\boldsymbol{F}_2}^2,&\text{if } E/F \text{ is unramified,} \\ \overline{\boldsymbol{F}_2}^{q+1},&\text{if } E/F \text{ is ramified,}
\end{cases}$$ via the map
\[ f \longmapsto \begin{cases}
  (f(1), f(s)),&\text{if } E/F \text{ is unramified;} \\
 (f(1), f(r), \cdots, f(r^q)),&\text{if } E/F \text{ is ramified.}
\end{cases}\]

Now we consider the $PD^\times/U_1\simeq D_{2(q+1)}$-equivariant map $\varepsilon:\pi^{U_1}\longrightarrow\overline{\boldsymbol{F}_2}$. When $E/F$ is unramified, $s\cdot f(1)=f(s), s\cdot f(s)=f(1)$ and $r\in C_{q+1}$ acts trivially and so $\varepsilon(f)=f(1)+f(s)$. When $E/F$ is ramified, $r\cdot f(r^j)=f(r^{j+1\pmod {q+1}}),s\cdot f(r^j)=f(r^{-j\pmod{q+1}})$. Thus $\varepsilon(f)=f(1)+f(r)+\cdots+f(r^q)$. Since $M^{U_1}$ is the kernel of $\varepsilon$, fix a suitable basis of $\pi^{U_1}$. Then we have
\begin{align*}
    M^{U_1}\simeq\begin{cases}
        \{(a_0,a_1)\in\overline{\boldsymbol{F}_2}^2|\ a_0+a_1=0\},&  E/F\ \textrm{is\ unramified};\\
        \{(a_0,\cdots,a_q)\in\overline{\boldsymbol{F}_2}^{q+1}|\ a_0+\cdots+a_q=0\},&E/F\ \textrm{is\ ramified}.
    \end{cases}
\end{align*}

Followed by the exact sequence \eqref{f41}, denote by $\iota$ the embedding map $(\chi\circ\det)^{U_1}\hookrightarrow M^{U_1}$. Then for any $\lambda\in \mathrm{Hom}_{D_{2(q+1)}}(M^{U_1},\boldsymbol{1})$,
since $\chi\circ\det$ is trivial on $U_1$, we have
\begin{align*}
    f_5(\lambda)=\lambda\circ\iota=\begin{cases}
    \lambda(1,1),& E/F \mathrm{\ is\  unramified};\\
    \lambda(1,\cdots,1),& E/F\ \mathrm{is\  ramified}.
\end{cases}
\end{align*}

 When $E/F$ is unramified, dim $M^{U_1}=1$ and so $f_5(\lambda)=\lambda(1,1)=1$, not a zero map. 

 When $E/F$ is ramified, we define 
\begin{align*}
    \lambda(a_0,\cdots,a_q)=\displaystyle\sum_{i=0}^q ia_i.
\end{align*}
Then we will verify that it is $D_{2(q+1)}$-invariant. Here all the indices are taken modulo \( q+1 \).

For the action of $r$:
\begin{align*}
    \lambda(r\cdot(a_0,\cdots,a_q))=\displaystyle\sum_{i=0}^{q}ia_{i+1}=\displaystyle\sum_{i=0}^q(i-1)a_i=\displaystyle\sum_{i=0}^q ia_i-\displaystyle\sum_{i=0}^q a_i=\displaystyle\sum_{i=0}^q i a_i.
\end{align*}
The last equality holds since $(a_0,\cdots,a_q)\in M^{U_1}$.

For the action of $s$:
\begin{align*}
    \lambda(s\cdot(a_0,\cdots,a_q))=\displaystyle\sum_{i=0}^qia_{-i}=\displaystyle\sum_{i=0}^q(-i)a_i=\displaystyle\sum_{i=0}^qia_i.
\end{align*}
The last equality holds since $\ell=2$. Therefore, $\lambda$ is $D_{2(q+1)}$-invariant. Moreover, since $\mathrm{Hom}_{D_{2(q+1)}}(M^{U_1},\boldsymbol{1})$ is one-dimensional, it is spanned by $\lambda$. Then 
\begin{align*}
    \lambda(1,\cdots,1)=\displaystyle\sum_{i=0}^q i\equiv\begin{cases}
        1\pmod 2, &\mathrm{when}\  q\equiv1\pmod4;\\
        0\pmod 2, &\mathrm{when}\  q\equiv3\pmod4.
    \end{cases}
\end{align*}
In a short summary, $f_5$ is a zero map if and only if $E/F$ is ramified and $q\equiv3\pmod4$. 
\end{proof}
Followed by Lemma \ref{f5zero}, $\mathrm{Sp}_\chi$ is distinguished if and only if $f_5$ is a zero map. It is equivalent to the conditions that $\chi|_{F^\times}=\boldsymbol{1}$, $E/F$ is ramified and $q\equiv3\pmod4$. Moreover,
\begin{align*}
    \mathrm{dim}\ \mathrm{Hom}_{D^\times}(\mathrm{Sp}_\chi,\boldsymbol{1})=\begin{cases}
        1,\ E/F\ \mathrm{is\ ramified\ and}\ q\equiv3\pmod4;\\
        0,\ \mathrm{otherwise}.
    \end{cases}
\end{align*}
This finishes the proof.

