For the action of $r$:
\begin{align*}
    \lambda(r\cdot(a_0,\cdots,a_q))=\displaystyle\sum_{i=0}^{q}ia_{i+1}=\displaystyle\sum_{i=0}^q(i-1)a_i=\displaystyle\sum_{i=0}^q ia_i-\displaystyle\sum_{i=0}^q a_i=\displaystyle\sum_{i=0}^q i a_i.
\end{align*}
The last equality holds since $(a_0,\cdots,a_q)\in M^{U_1}$.

For the action of $s$:
\begin{align*}
    \lambda(s\cdot(a_0,\cdots,a_q))=\displaystyle\sum_{i=0}^qia_{-i}=\displaystyle\sum_{i=0}^q(-i)a_i=\displaystyle\sum_{i=0}^qia_i.
\end{align*}
The last equality holds since $\ell=2$. Therefore, $\lambda$ is $D_{2(q+1)}$-invariant. Moreover, since $\mathrm{Hom}_{D_{2(q+1)}}(M^{U_1},\boldsymbol{1})$ is one-dimensional, it is spanned by $\lambda$. Then 
\begin{align*}
    \lambda(1,\cdots,1)=\displaystyle\sum_{i=0}^q i\equiv\begin{cases}
        1\pmod 2, &\mathrm{when}\  q\equiv1\pmod4;\\
        0\pmod 2, &\mathrm{when}\  q\equiv3\pmod4.
    \end{cases}
\end{align*}
In a short summary, $f_5$ is a zero map if and only if $E/F$ is ramified and $q\equiv3\pmod4$.

\label{thm42}
        Let $\pi$ be a $\sigma$-selfdual supercuspidal representation of $\mathrm{GL}_2(E)$. Assume that $\ell\neq2$. Then the followings are equivalent:
        \begin{enumerate}
            \item $\pi$ is $\mathrm{GL}_2(F)$-distinguished;
            \item $\pi$ is not $\omega_{E/F}$-distinguished;
            \item Langlands parameter $\varphi_\pi$ is conjugate-orthogonal.
        \end{enumerate}
        In particular, a $\sigma$-selfdual supercuspidal representation is either $\mathrm{GL}_2(F)$-distinguished or $(\mathrm{GL}_2(F),\omega_{E/F})$-distinguished, but not both.

\label{sccriterion}
Let $\pi$ be a $\sigma$-selfdual supercuspidal representation of $\mathrm{GL}_2(E)$,
with relative degree $m \in \{1,2\}$ and distinction character $\delta_0$.
\begin{enumerate}
\item If $\ell = 2$, then $\pi$ is always $D^\times$-distinguished.
\item If $\ell \neq 2$ and $p\neq2$, then $\pi$ is $D^\times$-distinguished if and only if 
\begin{align*}
    \begin{cases}
    \delta_0\ \mathrm{is\ the\ trivial\ character}, &\mbox{when}\ m=1;\\\
    \delta_0=\omega_{\mathcal{D}/\mathcal{D}_0},& \mbox{when}\ m=2.
\end{cases}
\end{align*}
\end{enumerate}

\label{pil=2}Assume $\ell=2$. Then the followings are equivalent:
\begin{enumerate}
    \item $\pi=\pi(\chi_1,\chi_2)$ is $\mathrm{GL}_2(F)$-distinguished;
    \item  $\chi_1\chi_2^\sigma=\boldsymbol{1}$ or $\chi_1|_{F^\times}=\chi_2|_{F^\times}=\boldsymbol{1}$ with $\chi_1\neq\chi_2$.
\end{enumerate}
